            if(row[1]!=null)mon.id=row[1];
            if(row[2]!=null)mon.level=row[2];
            if(row[3]!=null)mon.xp=row[3];
            if(row[4]!=null)mon.reg=regions[row[4]];
            if(row[5]!=null)mon.where=places[row[5]];
