                if ($('#evt-pick')?.classList.contains('open') || visible($('#evt-pick'))) {
                    this.ownedDialog=this.e.settings.optimizeRaid?{type:'team',key,optimized:false}:null;
                    if(!this.e.settings.optimizeRaid)this.e.status='请手动配置团体战队伍，或开启优化特殊战队伍';
                }
