                if(!job.id||!uids.length){this.fail('无法核对地下通道归队队员，请手动领取后重新开始');return;}
                if(d.click(take,'领取地下通道归队与奖励')){this.state.underCollect={id:String(job.id),uids,at:now};this.own('receipt','.ug-back');e.persist();}return;
