            if(!modal.matches('.rk-modal:not(.lgp-modal)')||!modal.querySelector('.rk-q'))return skip('无法核对升阶窗口');
            const costText=modal.querySelector('.dc-fact b')?.textContent||'';
            const counts=costText.match(/\d+/g);
