                if((savedDaily?.base.mode??mode)==='legend'&&!selectedLegendIds(savedDaily?normalizeSettings(savedDaily.base):this.settings).length)throw new Error(LEGEND_TARGET_REQUIRED);
                const {tower,event,zone,league}=s.adv;
