            if (!['wild','trainer'].includes(b.kind) || node && !['wild','trainer'].includes(node.type)) return null;
            if (b.kind==='wild' && (!b.enemies?.length || b.enemies.some(m=>!MONS.has(m.id)||m.shiny||MONS.get(m.id).legend))) return null;
